/* @lc app=leetcode id=1361 lang=kotlin */
class Solution { fun validateBinaryTreeNodes(n: Int, leftChild: IntArray, rightChild: IntArray): Boolean = IntArray(n).also { inDeg -> (0 until n).forEach { i -> listOf(leftChild[i], rightChild[i]).filter { it != -1 }.forEach { inDeg[it]++ } } }.let { inDeg -> (0 until n).singleOrNull { inDeg[it] == 0 }?.let { root -> BooleanArray(n).also { vis -> vis[root] = true }.let { vis -> java.util.LinkedList<Int>().also { q -> q.add(root) }.let { q -> intArrayOf(1, 1).let { v -> run { while (q.isNotEmpty() && v[1] == 1) q.poll().let { curr -> listOf(leftChild[curr], rightChild[curr]).filter { it != -1 }.forEach { child -> if (vis[child]) v[1] = 0 else vis[child] = true.also { v[0]++ } } } }.let { v[1] == 1 && v[0] == n } } } } } ?: false } }